class Solution {
public:
    long long maximumBeauty(vector<int>& flowers, long long newFlowers, int target, int full, int partial) {
        int n = flowers.size();
        for (int& f : flowers) f = min(f, target);
        sort(flowers.begin(), flowers.end());
        if (flowers[0] >= target) return (long long)n * full;
        vector<long long> pref(n + 1, 0);
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + flowers[i];
        long long ans = 0;
        int j = 0;
        for (int i = 0; i <= n; i++) {
            long long neededFull = (long long)(n - i) * target - (pref[n] - pref[i]);
            if (neededFull > newFlowers) continue;
            long long rem = newFlowers - neededFull;
            if (i == 0) {
                ans = max(ans, (long long)(n - i) * full);
                continue;
            }
            while (j < i && (long long)flowers[j] * j - pref[j] <= rem) {
                j++;
            }
            int idx = min(j - 1, i - 1);
            long long remAfter = rem - ((long long)flowers[idx] * (idx + 1) - pref[idx + 1]);
            long long minVal = min((long long)target - 1, (long long)flowers[idx] + remAfter / (idx + 1));
            ans = max(ans, (long long)(n - i) * full + minVal * partial);
        }
        return ans;
    }
};

class Solution {
    public long maximumBeauty(int[] flowers, long newFlowers, int target, int full, int partial) {
        int n = flowers.length;
        for (int i = 0; i < n; i++) flowers[i] = Math.min(flowers[i], target);
        Arrays.sort(flowers);
        if (flowers[0] >= target) return (long) n * full;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + flowers[i];
        long ans = 0;
        int j = 0;
        for (int i = 0; i <= n; i++) {
            long neededFull = (long) (n - i) * target - (pref[n] - pref[i]);
            if (neededFull > newFlowers) continue;
            long rem = newFlowers - neededFull;
            if (i == 0) {
                ans = Math.max(ans, (long) (n - i) * full);
                continue;
            }
            while (j < i && (long) flowers[j] * j - pref[j] <= rem) {
                j++;
            }
            int idx = Math.min(j - 1, i - 1);
            long remAfter = rem - ((long) flowers[idx] * (idx + 1) - pref[idx + 1]);
            long minVal = Math.min((long) target - 1, (long) flowers[idx] + remAfter / (idx + 1));
            ans = Math.max(ans, (long) (n - i) * full + minVal * partial);
        }
        return ans;
    }
}

/**
 * @param {number[]} flowers
 * @param {number} newFlowers
 * @param {number} target
 * @param {number} full
 * @param {number} partial
 * @return {number}
 */
var maximumBeauty = function(flowers, newFlowers, target, full, partial) {
    const n = flowers.length;
    for (let i = 0; i < n; i++) flowers[i] = Math.min(flowers[i], target);
    flowers.sort((a, b) => a - b);
    if (flowers[0] >= target) return n * full;
    const pref = new Array(n + 1).fill(0n);
    for (let i = 0; i < n; i++) pref[i + 1] = pref[i] + BigInt(flowers[i]);
    let ans = 0n;
    let j = 0;
    const NF = BigInt(newFlowers);
    const T = BigInt(target);
    const F = BigInt(full);
    const P = BigInt(partial);
    for (let i = 0; i <= n; i++) {
        const neededFull = BigInt(n - i) * T - (pref[n] - pref[i]);
        if (neededFull > NF) continue;
        const rem = NF - neededFull;
        if (i === 0) {
            const score = BigInt(n - i) * F;
            if (score > ans) ans = score;
            continue;
        }
        while (j < i && BigInt(flowers[j]) * BigInt(j) - pref[j] <= rem) {
            j++;
        }
        const idx = Math.min(j - 1, i - 1);
        const remAfter = rem - (BigInt(flowers[idx]) * BigInt(idx + 1) - pref[idx + 1]);
        let minVal = BigInt(flowers[idx]) + remAfter / BigInt(idx + 1);
        if (minVal > T - 1n) minVal = T - 1n;
        const score = BigInt(n - i) * F + minVal * P;
        if (score > ans) ans = score;
    }
    return Number(ans);
};
